head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[header > P > id]<br/>Header 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "Header 컴포넌트를 구별할 수 있는 유일값을 설정할 수 있어야 합니다.",
        "값을 설정하지 않으면 화면 렌더링 과정에서 임의의 ID 값이 설정되어야 합니다.",
        "스크립트에서 해당 컴포넌트에 접근하려면 ID 값을 반드시 설정하여야 합니다.",
        "화면 렌더링 과정에서 설정한 id 속성이 Scope 적용없이 그대로 사용되어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}

// 예약어 id 로 인한 오류 발생 여부 확인용 카운터
scwin.gErrCount = 0;
window.addEventListener("error", function () { scwin.gErrCount++; });



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 렌더된 Header 의 id 속성 확인 (설정 / 미설정 / Scope 적용 여부)
scwin.btn_getId_onclick = function (e) {
    let elTarget = document.querySelector("#target1");
    let arrHeader = elTarget.parentNode.querySelectorAll("header");
    let elAuto = arrHeader[1];
    let elButton = document.querySelector("[id$='btn_getId']");

    wf_body_bottom.getObj("scwin").setReturnValue("id 설정 - 렌더된 id : " + elTarget.id + " , '#target1' 조회 개수 : " + document.querySelectorAll("#target1").length);
    wf_body_bottom.getObj("scwin").setReturnValue("id 미설정 - 자동 부여된 id : " + (elAuto.id === "" ? "(없음)" : elAuto.id));
    wf_body_bottom.getObj("scwin").setReturnValue("Scope 적용 여부 - header 의 id : " + elTarget.id + " , 비교용 WebSquare button(btn_getId) 의 렌더 id : " + elButton.id);
};



// 스크립트에서 Header 접근 가능 여부 확인 (id 설정본 vs id 미설정본)
scwin.btn_getScriptAccess_onclick = function (e) {
    let elSet = document.querySelector("#target1");
    let elUnset = document.querySelector("#target2");

    wf_body_bottom.getObj("scwin").setReturnValue("스크립트 접근 - id 설정(target1) 조회 결과 : " + (elSet === null ? "조회 실패" : "조회 성공 (" + elSet.tagName.toLowerCase() + ")") + " , id 미설정 Header 를 지정 id(target2) 로 조회한 결과 : " + (elUnset === null ? "조회 실패" : "조회 성공"));
};



// 예약어(style) 를 id 로 설정한 Header 의 렌더 결과와 오류 발생 여부 확인
scwin.btn_getReservedId_onclick = function (e) {
    let elReserved = document.querySelector("header[id='style']");

    wf_body_bottom.getObj("scwin").setReturnValue("예약어(style) id 설정 - 렌더된 id : " + (elReserved === null ? "(조회 실패)" : elReserved.id) + " , 페이지 로드 후 발생한 JS 오류 건수 : " + scwin.gErrCount);
};
